class Solution:
    def consecutiveNumbersSum(self, n: int) -> int:
        while n % 2 == 0:
            n //= 2
        count = 0
        d = 1
        while d * d <= n:
            if n % d == 0:
                count += 1 if d * d == n else 2
            d += 2
        return count

